/* Momentum: the heart of the app (Jeremy, 2026-10-02). Every curiosity carries a momentum note on how it moves
   the plot and the themes forward and how it pulls the audience's attention on into what comes next, plus three
   sliders every curiosity shares so momentum itself can be automated. The shape is momentum/notes.js's FIELD
   (the Momentum thread, PR #18), which reads this field first.

   momentum: { push: 0..5, plot, theme, pull, cue: visual | audio | thought | movement | plot, tryThis }
   Shared sliders: push ("Pushes the story", 0 to 5, starting at the note's push), pointsAhead ("Points ahead")
   and themeLink ("Tied to a theme").

   NOTES is [push, plot, theme, pull, cue, tryThis] per curiosity: 84 written by the Momentum thread, the rest
   written here for each curiosity. They are film knowledge, not measurements. Loaded after db-finish.js, so the
   shared sliders don't count toward its "at least three sliders of its own". */
(function (DB) {
  const NOTES = {
    "absurdity": [2,"Each step further from real life raises the question of how the characters will get out of this mess.","How seriously the characters take the nonsense says whether the film sees the world as mad or themselves as the mad ones.","Once things stop making sense, the audience waits to see just how far it will go.","thought","Let nobody blink at the strangest thing in the room."],
    "actionCutRate": [2,"Faster cuts during action push the scene toward its climax and the next turn.","Speed in action shows chaos or control, depending on whether it feels clear.","Each cut throws the eye to something new, keeping the audience racing to keep up.","visual","Cut faster as the fight builds, then hold one wide shot to show the result."],
    "alliances": [3,"Switching sides changes who has power, which changes where the plot goes.","Shifting loyalties show how shallow or deep friendships really are.","The audience tracks who is with whom and waits for the next switch.","thought","Have the most loyal person switch sides at the worst moment."],
    "angleChange": [2,"Cutting on a line or an action decides which moment the audience lands on.","Cutting on actions feels physical; cutting on words feels like a debate.","Cutting a beat early or late changes when the audience gets the payoff, which sets comic timing.","visual","Cut to the listener's face a beat after the insult, not before."],
    "angleCount": [1,"More camera positions give the edit more ways to speed up and build the scene.","Few positions feel calm and staged; many feel busy and broken up.","Each new position is a new view, which refreshes attention.","visual","Save one new camera position for the turn of the scene."],
    "angleFamily": [2,"Whether a scene is cut up, shot in one go, or a montage sets how time passes in it.","One unbroken shot feels honest and trapped; a montage feels like time rushing by.","An unbroken shot makes the audience wait for the cut that never comes.","visual","Shoot the scene's most awkward moment in one unbroken shot, and let the silence be the joke."],
    "angleHeight": [2,"Changing the camera height marks who is gaining or losing power in a scene.","Looking up at someone makes them big; looking down makes them small.","A sudden drop to the floor or jump overhead tells the audience the power has shifted.","visual","Lower the camera on a character each time they gain the upper hand."],
    "angleToAction": [2,"A close shot of a hand doing something tells the audience that action matters later.","Matching shot to action says what deeds the film cares about.","A sudden close-up of an action makes the audience remember it for later.","visual","Cut close on a hand pocketing the key, then never mention it until the end."],
    "angleToLine": [3,"Matching the shot to a line tells the audience which lines carry the plot.","Playing against the line, like going wide on a confession, says the words are not the whole truth.","Moving close on a line tells the audience to listen hard to it.","thought","Go wide and far away on a big declaration to make it funny."],
    "anticipation": [1,"A wind-up before a move tells the audience something is about to happen and when.","Big wind-ups show eagerness or nerves; none shows calm control.","The wind-up makes the audience wait for the move, which is why it works for comedy.","movement","Give a character a huge wind-up for a tiny action, and let the payoff be anticlimactic."],
    "arcDirection": [4,"Whether someone grows or falls sets where the story must end, and every scene becomes a step toward it.","Growing, falling or changing others instead is the film's answer to whether people can really change.","Once the audience senses the direction, they watch every choice to see if it keeps them on course.","thought","Give the character who never changes one scene where everyone around them changes because of them."],
    "arcStage": [5,"Where the character stands in their change decides what they can do in this scene.","The arc is the theme acted out.","Watching someone change is the main reason to keep watching.","plot","Make each scene move them one stage, forward or back."],
    "arcTest": [5,"The test forces the character to act on what they have learned, so the plot turns.","The test proves the theme.","Everything has been pointing at the test.","plot","Make the test something only the new them could pass."],
    "arcs": [1,"Curved paths make actions read clearly but rarely change what happens.","Round paths feel natural and alive; straight lines feel mechanical or stiff.","The eye follows a curved path smoothly to where the movement ends.","movement","Swing a pointing hand in an arc that ends right on the thing it points at."],
    "artArrangement": [1,"How the art is hung tells us about the owner, not about what happens next.","Perfect rows show control; scattered art shows a messy or free mind.","One crooked picture in a perfect row pulls the eye, a classic small gag.","visual","Hang one picture crooked in a perfect row and let a character keep fixing it."],
    "aspect": [1,"A change in frame shape can mark a flashback, a dream or a new chapter.","A narrow box feels boxed in; a wide one feels open and epic.","When the frame changes shape, the audience knows they have entered a new world.","visual","Widen the frame the moment the hero finally gets out."],
    "atmosphere": [1,"Haze thickening in the air shows a place growing heavier, smokier or more dreamlike as the story goes on.","Visible beams in hazy air make an ordinary room feel sacred, haunted or remembered.","Beams of light through haze point like arrows, leading the eye to whatever stands where they land.","visual","Add a little haze so a single beam from a high window lands on the object the scene is about."],
    "audienceFeeling": [4,"What the audience feels decides whether they want the story to go on.","A film's themes are what it makes you feel about its ideas.","The audience leans in when they feel something they need resolved.","thought","Let the audience know something the character does not, so they feel dread or hope."],
    "backCost": [1,"The cost of the crowd's clothes tells us what kind of world the hero has walked into.","Rich against poor crowds shows class and who belongs.","A hero dressed cheaper or richer than the crowd stands out and becomes the focus.","visual","Dress the crowd in luxury when the broke hero walks in."],
    "backCoverage": [1,"How covered the crowd is sets the place and its rules more than the plot.","Bare or fully covered crowds show a world's rules about the body and shame.","A hero covered too much or too little for the crowd stands out instantly, often for a laugh.","visual","Put a fully bundled-up hero on a beach full of swimmers."],
    "backEra": [1,"The era of the crowd's clothes sets when the story happens and its rules.","Old against new clothes shows the past pushing against the present.","One background person from the wrong era is a visual gag the eye hunts for.","visual","Hide one person in modern clothes in a period crowd as a running joke."],
    "backFunction": [1,"Work wear, armor or riding clothes on the crowd tell us what job this world runs on.","What the crowd is dressed to do shows what this world values or fears.","Clothes for a danger that has not appeared yet make the audience wait for it.","visual","Dress every extra in helmets before the hero learns why."],
    "backPeriodTruth": [1,"Getting the period right keeps the world believable, without changing what happens.","Loose period clothes say the film is playing with the past, not copying it.","A clearly wrong costume pulls the eye, which can be a deliberate joke.","visual","Keep the crowd exact to the period so one wrong detail lands as a gag."],
    "backSameness": [1,"A crowd dressed alike is one force the main character must face.","Sameness speaks to conformity, order, control.","One person dressed differently in a uniform crowd becomes the next thing we watch.","visual","Break the sameness with one person who will matter later."],
    "backUtility": [1,"Whether the crowd dresses for looks or work tells us what kind of place this is.","Looks against function shows a world of show against a world of labor.","One person dressed for show among workers draws the eye to them.","visual","Put the vain character in fancy clothes among a crew in overalls."],
    "backVsMain": [1,"When the main character stands out from the crowd, the plot is about them against the group.","Standing out against blending in is a theme of identity.","The eye finds the one who is different.","visual","Make the crowd slowly start dressing like the main character as they win people over."],
    "backWear": [1,"Worn or torn crowd clothes tell us how hard life is here or what just happened.","Worn clothes show struggle and history; new clothes show money or fakeness.","Clothes getting dirtier scene by scene make the audience feel things are getting worse.","visual","Make the crowd's clothes a little more worn each time the hero returns."],
    "balloon": [2,"Speech balloons move the story through what people say; caption boxes can tell the reader things the characters don't know.","When a caption knows more than the characters, it can show irony, fate or a narrator's view.","A caption that hints at trouble the characters can't see makes the reader turn the page to watch it hit.","thought","Put a caption that says 'It was going to be a perfect day' over a panel where everything is about to go wrong."],
    "beliefShown": [3,"A belief shown in a big choice pushes the plot; one only hinted at waits to be tested.","When actions and words do not match, the film is asking what people truly value.","Saying one thing and doing the opposite makes the audience watch for when the gap gets exposed.","thought","Have the character loudly say they do not care, then quietly do the caring thing when no one is looking."],
    "blink": [1,"A blink can mark the moment a thought changes, showing a decision before it is spoken.","Not blinking can make a character feel inhuman, cold or completely focused.","A blink on a thought makes the audience read the face for what was just decided.","visual","Have a liar blink slightly too often when telling the big lie."],
    "blocking": [3,"Moving people closer or apart in the room shows alliances forming and breaking.","Who stands in the middle shows who holds power right now.","When someone steps into the center, the audience knows the scene now belongs to them.","movement","Have the winner of the argument end up standing in the middle."],
    "bodyEnter": [3,"Someone entering changes who is in the room, and so changes what can happen next.","Who arrives and who leaves shows who belongs and who is shut out.","An entrance grabs attention; a figure bursting in is a ready-made laugh or shock.","movement","Let a character burst in from the side the others were not watching."],
    "breakage": [3,"Something breaking can't be undone: a shattered vase or cracked dam forces the story into a new direction.","What breaks and what holds shows what is fragile in these lives and what is tough.","A crack spreading slowly makes the audience hold their breath, waiting for the full shatter.","movement","Let a crack creep across the glass for a few seconds before it finally shatters; for comedy, have it hold, then break when someone sighs with relief."],
    "breath": [1,"A breath before a line signals that the line matters and is hard to say.","Showing breath reminds the audience these are bodies with fear and effort, not just voices.","An audible breath makes the audience wait for whatever comes after it.","audio","Put a long breath before the confession, then have the character say something else entirely."],
    "breather": [2,"A quiet scene after a big one lets the audience catch up, so the next push hits harder.","Breathers show what the characters are fighting for.","A breather resets attention so it can be pulled again.","thought","Put a quiet moment of warmth right before the hardest scene."],
    "callResponse": [2,"One shot asking and the next shot answering ties scenes together and moves the story along by questions and replies.","Who answers whom across the cuts shows who is connected, even when they are far apart.","When one shot poses a question, the audience wants the next shot to answer it.","thought","End one scene on a question and cut straight to someone else saying the answer, for comedy, the wrong one."],
    "callback": [3,"A callback ties the present to the past and shows how far we have come.","A callback with a new meaning shows the theme growing.","Recognition is a strong pull: the audience loves to catch it.","thought","Bring back a line from the first scene with the opposite meaning."],
    "cameraCarry": [1,"A shaky camera says events are out of control; a still one says someone is in charge.","Steady feels ordered and watched; handheld feels raw and present.","Switching from still to shaky warns that the calm is over.","visual","Lock the camera still for a deadpan joke, so nothing distracts from the face."],
    "cameraMove": [2,"A push in says 'pay attention, this is important'; a pull back says 'look what this means'.","Moving toward or away from someone is moving toward or away from understanding them.","The move itself carries the eye to the end of it.","movement","Push in slowly through a whole speech that changes someone's mind."],
    "cameraOwner": [3,"Handing the camera to the player lets them choose where to look, so the story waits on them.","Who controls the view shows who is in charge: the storyteller or the player.","Taking control back from the player tells them something important is about to happen.","plot","Take the camera away from the player only for the key reveal."],
    "cameraShake": [2,"A shake on an impact or explosion tells the audience something big just hit.","A shaking world feels unsafe and out of control.","A sudden shake jolts attention onto the cause, and a tiny shake for a small thud can be funny.","movement","Shake the camera hard for a door slam to oversell it for a laugh."],
    "catharsis": [4,"The release at the end pays off everything the plot built.","Catharsis is where the theme lands in the body.","Everything before it pulls toward it.","thought","Make the release come from the character's own choice."],
    "changeShows": [2,"A new habit or outfit marks that the character has crossed a line and cannot easily go back.","Showing the inner change on the outside makes the film's idea of growth something you can see.","The audience starts checking each scene for the new walk or dropped habit, tracking how far they have come.","visual","Drop one habit the audience saw in act one, and let another character notice it out loud."],
    "chaosInRoom": [3,"One chaotic person in an orderly room breaks the plan the room was there for.","Chaos against order is the theme of rules and the people who cannot follow them.","The audience watches the calm room, waiting for the moment it all falls apart.","movement","Set the scene somewhere solemn, like a funeral, and add one loose person."],
    "characterPath": [3,"Where someone walks is where the plot goes: toward a door, toward a person, away from home.","Paths that cross or keep missing each other are the theme of meeting and parting.","The eye follows a walking person to where they are going.","movement","End every walk on the thing the next beat is about."],
    "characterSpeed": [2,"A character speeding up or slowing down shows they are rushing toward something or dreading it.","How fast someone moves shows how much they want what they are heading for.","A sudden change of pace makes the audience ask what they just noticed.","movement","Have a character stop dead mid-walk when they see the thing that changes the scene."],
    "characterToLens": [2,"Walking toward the camera brings a character, and their problem, right up to us.","Coming closer reads as confronting; walking away reads as giving up or escaping.","Someone walking toward us makes the audience wait for them to arrive and speak.","movement","Have a character walk straight at the camera until their face fills the frame, then cut."],
    "chemistry": [2,"A spark between two people makes the audience want them together, which pulls the plot along.","Chemistry shows what people need from each other.","The audience watches for every look and wonders when the spark will catch.","visual","Have them say the same word at the same time, then look away."],
    "clothResponse": [1,"A cape or coat starting to flutter tells the audience the moment of action has arrived.","Stiff clothes feel formal and held in; loose, fluttering ones feel free and wild.","Fluttering cloth keeps the shot alive with motion and draws the eye to the person wearing it.","movement","Have the hero's coat flap dramatically in the wind, then go limp and silly when the wind dies mid-speech."],
    "clump": [1,"Fur going from fine to matted shows a character going through hardship or neglect over the story.","Clean, fluffy fur feels cared for; clumped, matted fur feels wild, wet or forgotten.","A sudden change in how fur clumps tells the audience something happened to this creature off-screen.","visual","Show the pet fluffy at the start and matted after the storm so we know it has been through it."],
    "clutter": [1,"Clutter hides things; clearing it out can uncover the one thing the plot needs.","A cluttered or bare room shows a cluttered or empty life.","In clutter, the eye hunts; in a bare room, the one object wins.","visual","Strip the room bare before the moment that matters."],
    "cm-adaptability": [3,"A rigid character breaks against change while a flexible one bends, and that decides who survives the plot.","Bending versus holding your line asks when stubbornness is strength and when it is foolishness.","When a rigid person finally has to bend, the audience waits to see if they snap instead.","thought","Put a rigid character in a situation that changes every minute and refuse to let them leave."],
    "cm-agency": [4,"A proactive character starts events and drives the plot; a reactive one is dragged by it.","Answering life or starting it is how the film shows someone taking charge of who they are.","When a reactive character finally makes the first move, the audience leans in to see the result.","plot","Give a reactive character one scene where they act first, and have it go wonderfully wrong."],
    "cm-competence": [3,"Whether a character can actually do the job decides if the plan works or falls apart.","Skill versus clumsiness shows whether wanting something is enough to get it.","Watching a hopeless person attempt something hard keeps the audience on edge, and laughing.","movement","Give the least capable character the most important job and let them almost pull it off."],
    "cm-conflict": [4,"A confrontational character starts the fights that move the plot; an avoider lets problems pile up until they burst.","Walking into a fight or away from it shows how people handle what is wrong between them.","When an avoider finally confronts someone, the audience cannot look away.","plot","Have the avoider dodge a fight so hard they create a bigger fight with someone else."],
    "cm-control": [3,"A controlling character tries to steer events, and the plot pushes back by slipping out of their hands.","Holding on versus letting go is one of the oldest themes, and this shows where someone stands.","When control slips, the audience watches them scramble to grab it back.","plot","Let a control freak plan every detail, then have one tiny thing go wrong and watch them unravel."],
    "cm-emotion": [2,"Feeling-driven choices are fast and messy; reasoned ones are slow and cold, and both create trouble.","Heart versus head is how the film weighs what makes a good choice.","When a rational character finally breaks down, the audience is pulled into what sparked it.","thought","Have the coolest thinker in the room cry at something small and ridiculous."],
    "cm-focus": [2,"A narrow focus makes the character blind to something coming, setting up a surprise.","Seeing only one thing versus the whole world is a way to show selfishness or care.","When their focus snaps wide, the audience suddenly sees what they have been missing too.","visual","Widen the shot at the same moment the character finally looks up and notices the room."],
    "cm-freedom": [3,"Going your own way causes friction with the group, which pushes the story into conflict.","Fitting in versus standing apart is the film's question about who gets to be themselves.","When a conformist breaks ranks, the audience waits for the group to react.","thought","Have the conformist follow every rule so exactly that it becomes the most rebellious act in the room."],
    "cm-health": [3,"As health worsens, the character slides into their stress type and makes the choices that start the trouble.","Sliding toward stress or growing toward health is the film's picture of someone falling apart or coming together.","Each scene of drift makes the audience wonder how low they will go before they turn.","thought","Show them at their best early, so their worst behavior later hurts, and is funny, by contrast."],
    "cm-morality": [3,"Whose good someone serves first decides whether they help or betray when it matters.","Selfless versus selfish is the film's moral weighing scale, made into a person.","A selfish character doing one kind thing makes the audience wonder what they are really after.","thought","Have a selfish character do a good deed for a completely selfish reason, and say so."],
    "cm-motivation": [3,"Chasing approval makes choices that please others; an inner need makes choices that please no one but themselves.","Living for others' eyes versus your own is how the film asks what really matters.","When an approval seeker gets the praise and still feels empty, the audience wants to see what they do next.","thought","Give them the applause they wanted, then hold on their face while it does not help."],
    "cm-need": [3,"Chasing safety makes someone stay put; chasing freedom makes them leave, and the plot goes with them.","Security versus freedom is the film asking what a good life looks like.","When a safety seeker takes a step toward freedom, the audience watches to see if they run back.","thought","Give them the safe choice and the free choice in the same moment, and make them pick on screen."],
    "cm-openness": [4,"A secret held back is a ticking bomb that the plot will eventually set off.","Showing versus hiding yourself is the film's question about trust and being known.","Whatever a secretive character holds back, the audience wants to find out.","thought","Have a secretive character almost reveal something, then change the subject badly."],
    "cm-perspective": [3,"A mind that starts to widen lets the character see a choice that was invisible to them before.","Opening up is how the film shows that understanding others is possible, or costly.","A glimpse of a widening mind makes the audience hope it keeps going and fear it snaps shut.","thought","Let them hear the other side once, pause, then go right back to their old opinion."],
    "cm-risk": [3,"A reckless choice opens doors and causes disasters; a cautious one stalls and frustrates.","How much risk someone takes shows what the film thinks about fear and courage.","The audience leans in whenever a reckless person approaches something they should not touch.","movement","Let the most cautious character take one wildly reckless step, and show everyone's faces."],
    "cm-role": [4,"The role decides what this person does to the others: block them, help them, tempt them or shake them loose.","A foil or mirror puts a second way of living beside the hero's, so the film's question gets argued with bodies.","A character who is unaware of the role they play makes the audience wait for the moment they find out.","plot","Let a trickster deliberately play the mentor for one scene, and let the advice be hilariously wrong."],
    "cm-stability": [3,"A catalyst starts change in others; a stabilizer resists it, so their pairing sets the plot's speed.","Holding steady versus shaking things up is the film asking whether change is worth the chaos.","When a known stabilizer suddenly causes trouble, the audience sits up to see why.","plot","Pair a calm stabilizer with a catalyst who keeps undoing everything they just fixed."],
    "cm-temperament": [1,"A chaotic life creates small messes that can tip into plot problems at the worst time.","Order versus chaos in someone's daily life mirrors whether they can handle the story's bigger mess.","A chaotic character's room or desk makes the audience wonder what they will lose next.","visual","Open on the chaotic character's apartment and hide the one thing they need in the pile."],
    "cm-truth": [4,"Every lie told is a debt the plot will come to collect.","Honest versus deceptive is the film asking what truth costs and what lies protect.","Once the audience knows a lie is out there, they wait for it to be caught.","plot","Let a lie grow bigger with every scene until it needs a costume and a fake name."],
    "cm-worldview": [2,"An idealist pushes for a better outcome while a cynic expects the worst, and their clash moves decisions.","Hope versus doubt is the film asking whether things can really get better.","When the cynic is proven wrong, or the idealist proven right, the audience wants to see the fallout.","thought","Pair a cheerful idealist with a cynic and let the cynic be right about everything except the one thing that matters."],
    "colorAccent": [2,"One color that pops marks the thing the plot will need.","A single color can carry the theme through the film.","The eye goes straight to the one color.","visual","Give the accent color only to the thing that matters."],
    "colorCount": [1,"How many colors are in the frame shapes the mood, not the plot.","Few colors feel unified and controlled; many feel lively and chaotic.","In a frame of one color, a single different color grabs the eye at once.","visual","Keep the frame in one color and give only the important object a second one."],
    "colorDrift": [2,"Color drifting through a scene shows the mood moving.","Color moving from warm to cold is a theme of loss.","A slow color change pulls attention without anyone noticing why.","visual","Drift colder through a scene that ends in a loss."],
    "colorFilter": [1,"A tint across the picture can mark a separate place or time in the story.","A heavy tint says we are seeing the world through a feeling, not as it is.","When the tint changes, the audience knows they have crossed into another part of the story.","visual","Give each separate storyline its own tint so the audience always knows where they are."],
    "colorRange": [1,"Moving from black and white to color can mark a memory, a dream or a change in the hero.","Draining color feels like grief or the past; full color feels alive and present.","When color creeps in or drains out, the audience knows something has shifted.","visual","Let the first color appear in the frame when the hero falls in love."],
    "colorTemp": [1,"A switch from warm lamp light to cold daylight marks that the cozy part is over and the hard part has begun.","Warm light feels like home and safety; cold light feels like the outside world and the truth.","When warm and cold light meet on one face, the audience feels a pull between two places and wants to see which wins.","visual","Keep a home scene warm, then let a cold blue light from an opened door fall across it."],
    "comedyDevice": [2,"The kind of joke sets how the scene moves: slapstick moves bodies, wordplay moves ideas.","What kind of jokes a film tells shows its view of people.","Changing the kind of joke keeps the laughs fresh.","thought","Change the kind of joke when the laughs start to fade."],
    "comedyTopic": [1,"What the jokes keep poking at points to the problem the plot will have to face for real later.","The subject a film laughs at, and who it punches, is what the film thinks about the world.","A touchy subject makes the audience lean in, wondering how far the film will dare to go.","thought","Pick one touchy subject and joke closer to it in each act."],
    "comicBeat": [3,"Setup and payoff are the film's own promise and delivery, in miniature.","A payoff that lands on a theme makes the joke mean something.","A setup hangs in the air; the audience waits for its payoff.","thought","Pay off a joke from act one in act three's climax."],
    "comicEdit": [2,"A smash cut skips straight to the result, which jumps the plot ahead with a laugh.","Cutting to what really happened mocks what a character claims about themselves.","A cut that answers a line makes the audience expect the edit itself to tell the next joke.","visual","Have them say 'this will be easy', then smash cut to the disaster."],
    "comicEscalation": [3,"Each joke topping the last pushes the scene to a breaking point.","How far things can go is a theme of excess.","The audience wants to see how far it will go.","thought","Go one step further than feels safe on the third beat."],
    "comicFlaw": [4,"The flaw makes the character choose wrong, and each wrong choice drives the plot.","The flaw is often what the film is about: vanity, greed or pride, and what it costs.","The audience knows the flaw will trip them again and waits to see how.","thought","Put the thing their flaw wants most right next to the thing they need."],
    "comicPremise": [4,"The funny 'what if' is the engine of the story: every scene is that idea pushed further.","The premise shows what the film thinks is ridiculous about people.","A clear premise makes the audience wonder how far it can be taken, and wait to find out.","plot","State the 'what if' in the first scene, then make each scene push it one step further."],
    "comicReaction": [2,"How others react to a joke shows where they stand with the joker and what they will do next.","A slow burn or a stare says who in the room is fed up and who is still enjoying it.","The audience watches the listener's face as much as the joker, waiting for it to crack.","visual","Cut to the listener's face a beat late, after the joke, and hold it."],
    "comicRegister": [1,"Keeping the performance at one size lets the story's real turns stand out when someone finally breaks it.","A straight face in a crazy world is a theme of people holding it together.","When a deadpan character finally cracks, the audience has been waiting for it all along.","visual","Keep one character dead straight all film and let them crack only at the climax."],
    "comicSound": [1,"A pointed silence or a sting marks the moment a plan has just gone wrong.","Silly sound against serious faces shows how small the characters' troubles really are.","A sudden silence makes the audience lean in, waiting for the sound that ends it.","audio","Cut every sound out the instant after the worst thing is said."],
    "comicTiming": [1,"A well-timed pause lets the joke land cleanly so the scene can move on without stalling.","Rushing or waiting tells the audience whether these people are nervous, sure, or lost.","The beat of silence before the punchline makes the audience hold its breath for the laugh.","audio","Wait one beat longer than feels safe before the punchline, then cut on the laugh."],
    "composition": [1,"Leaving room in the frame for something to arrive makes the audience expect it.","Where people sit in the frame shows power and isolation.","Empty space on one side makes the eye wait for it to be filled.","visual","Frame someone at the edge of the shot before they are left out."],
    "contrast": [1,"Shadows creeping across a face as the scene goes on show the trouble growing without a word.","A face half lost in dark shadow says this person has something they are not showing.","When a shadow suddenly lifts off a face, the audience leans in, sensing the truth is about to come out.","visual","Let the shadow side of the face get darker each time the character dodges a question."],
    "contrastMap": [2,"Switching between opposites, quiet to loud, sparse to busy, gives the story a steady push and pull.","The opposites the film keeps returning to are its themes, made into feelings the audience senses.","After a long quiet stretch, the audience waits for the loud one, and the swing carries them forward.","thought","Pick one pair of opposites, like quiet and loud, and cut from one to the other at every big moment."],
    "cringe": [2,"An awkward moment usually costs the character something, a job, a date, a friend, that the plot must now fix.","Cringe shows the gap between how people see themselves and how others see them.","The audience squirms and wants to look away, but has to know how bad it gets.","visual","Keep the camera on the awkward face two beats after anyone would normally cut."],
    "curl": [1,"Smoke or water starting to curl and swirl shows something has disturbed a calm scene.","Gentle curls feel graceful and calm; tight, fast curls feel restless and troubled.","Curling smoke leads the eye along its path, often up and across to the next thing in the shot.","movement","Let a curl of smoke from a cigarette drift across the frame toward the person being talked about."],
    "cutArticulation": [2,"Short, clipped cuts make the action feel punchy; long blended cuts make it feel flowing and continuous.","Choppy cuts feel jumpy and nervous; smooth overlapping cuts feel dreamy and connected.","Sharp cuts jolt the audience to attention, while smooth ones carry them gently into the next shot.","visual","Use short, sharp cuts for the slapstick chase and slow blended cuts for the quiet morning after."],
    "cutRate": [3,"Cutting faster tells the audience the story is speeding toward something.","Fast against slow cutting is chaos against calm.","Every cut is a new thing to look at, so the cut rate is the rate attention is moved by the camera.","visual","Speed up the cutting as the scene nears its turn, then hold one long shot after it."],
    "cutawayGag": [1,"A quick cutaway to a memory can fill in backstory the plot needs without slowing down.","Cutting to what really happened shows the gap between what people say and the truth.","Once the film starts cutting away, the audience waits for the next line that will spark one.","visual","Cut to the memory that proves the line wrong, then straight back to their face."],
    "density": [2,"Smoke or fog thickening from a wisp to a wall cuts characters off and raises the danger.","Thick fog hides things and stands for confusion; clearing air stands for understanding.","A wall of smoke hides what is behind it, and the audience waits for something to step out.","visual","Let the fog grow too thick to see through, then have a figure walk out of it."],
    "depthOfField": [1,"A thin sharp zone hides what is behind; a deep one lets the background carry a clue.","A blurred world feels private and dreamy; a sharp one feels watchful.","With everything sharp, the eye can wander to a background gag or threat.","visual","Keep the whole room sharp so a background character can do something funny."],
    "dissenter": [4,"One person refusing the group turns the plot.","Dissent is a theme of courage and conscience.","The one who says no pulls every eye.","plot","Make the dissenter someone the audience did not expect."],
    "distraction": [3,"A distracted character misses what matters, which causes trouble.","Distraction is a theme of what we let slip.","The audience sees what the character misses and waits for it to hit.","thought","Let the audience see the danger while the character is distracted."],
    "doubleAct": [2,"A pair who need each other carry the plot forward together, even while they squabble.","Two people funnier together than apart is a theme of friendship and need.","Fast trading of lines makes the audience wait for the line that wins the round.","audio","Split the pair up for one scene so the audience misses them."],
    "dramaticRole": [4,"Each role has a job: the catalyst starts trouble, the challenger tests the hero, the mentor hands over what they need next.","Who plays mirror, foil or moral center tells the audience which way of living the film is weighing.","When a role snaps, like the anchor suddenly turning wildcard, the audience leans in to see what breaks next.","plot","Give every scene one catalyst, and make it the person the audience least expects."],
    "dread": [4,"Dread is the plot pulling forward before it arrives: the audience knows something is coming.","What a film makes us dread shows what it fears.","Dread holds attention by making the audience wait for the blow.","thought","Show the danger to the audience, not the character."],
    "dutch": [1,"Tilting the camera warns that things have gone wrong, even before anyone says so.","A tilted world feels unstable, crazy or guilty.","A sudden tilt makes the audience feel uneasy and watch for trouble.","visual","Tilt the camera only after the lie is told, and level it when it is found out."],
    "dynamicRange": [1,"A sudden loud line after quiet ones can mark a turning point in the scene.","A wide gap between quiet and loud shows a character barely holding something in.","The jump from whisper to shout jolts attention right onto that line.","audio","Keep every line quiet until the punchline, then go loud on just that one."],
    "eating": [1,"Eating while talking can slow a scene down or hide that someone is avoiding a hard subject.","Food shared or ignored shows comfort, closeness or tension at the table.","A full mouth delaying an answer makes the audience wait, and laugh, for the reply.","movement","Have someone take a huge bite right before they are asked the big question."],
    "egoClash": [3,"Two people who both need to be right keep blocking each other, which piles up the trouble.","A petty cause shows how pride makes people small.","The audience waits to see who will back down first, and suspects neither will.","thought","Make the cause of the fight as petty as possible, and the stakes as high as possible."],
    "element": [3,"Water, smoke, fire, sand or snow entering the scene often is the event: a flood, a fire or a storm the characters must face.","Each element carries meaning: fire for anger or danger, water for cleansing, snow for isolation.","When smoke or water appears, the audience knows it will spread and watches to see where it goes.","visual","Show a small wisp of smoke in the background early, long before anyone smells the fire."],
    "emoActions": [3,"A big action, like throwing something, changes the scene and can't be taken back.","Breaking things shows what a character can no longer hold in.","A gripped object makes the audience wait for it to be thrown or dropped.","movement","Give them an object to grip all scene and break it at the turn."],
    "emoContrastPrev": [3,"A scene that feels the opposite of the last one makes the story feel like it is moving.","Contrasts between scenes show the film's two sides.","A change in feeling from one scene to the next restarts attention.","visual","Follow every heavy scene with a lighter one, and the other way round."],
    "emoEyes": [1,"Where someone looks shows what they want next before they say it.","Looking away or looking straight on is the theme of shame and honesty.","The audience follows the eyes to what the character is looking at.","visual","Have them look at the door before they say they'll stay."],
    "emoHands": [1,"Fidgeting or clenched hands give away a secret or a plan the face is hiding.","Hands that betray the face show the gap between what people show and feel.","Restless hands catch the eye, and the audience wonders what they hide.","visual","Show the hands in close up while the face stays calm."],
    "emoMove": [1,"A frozen or restless body shows what the character is about to do before they do it.","Moving freely or held back shows whether someone is free or trapped.","A sudden change in how someone moves catches the eye and makes us wonder why.","movement","Freeze them still the moment they hear the bad news."],
    "emoRelease": [4,"When a held feeling finally comes out, it changes the character and often the plot's direction.","What it takes to let go shows what the film thinks about holding things in.","The audience waits through the whole scene for the feeling to burst.","plot","Hold the release back one scene longer than the audience expects."],
    "emoRoadCharacter": [4,"Where the character is on their emotional road decides what they can and can't do now.","The rises and falls of their road are the theme in motion.","The audience wants to know whether they will rise or fall next.","plot","Put them at their lowest point just before the big choice."],
    "emoRoadFilm": [4,"Where the whole film sits on its road sets up whether the next scene must lift or drop.","Alternating light and dark says life is never just one thing.","The audience feels the rise or fall and braces for the next swing.","plot","Follow every dark scene with a lighter one until the peak."],
    "emoShown": [3,"Letting a feeling show tells others the truth, and the plot moves when they learn it.","What showing a feeling costs is the theme of pride and vulnerability.","When only the audience can see it, they wait for the others to find out.","visual","Show the feeling only to the audience, and keep it hidden from everyone else."],
    "emoSpread": [2,"A feeling spreading through a room can turn a group toward a decision.","Feelings spreading show how connected, or how easily led, people are.","The audience watches the feeling move from face to face and wonders who will catch it next.","visual","Start a laugh with one person and let it spread around the room."],
    "emoTurn": [4,"A feeling that flips mid-scene changes what the character does next.","What turns the feeling, a word or a memory, shows what really matters to them.","The audience watches for the moment the feeling flips.","visual","Turn the feeling on one small object, like a photo found in a drawer."],
    "emoVoice": [2,"A voice that breaks tells the other characters the truth, which changes what they do next.","A feeling hidden in the voice is the theme of what people can't say.","A wavering voice makes the audience listen for the moment it cracks.","audio","Keep the voice steady through the whole speech and let it crack on the last word."],
    "emotion": [4,"The feeling of the beat drives what the characters do next.","The feelings a film keeps returning to are its themes.","A new feeling on a face is the strongest pull on the audience.","visual","Change the feeling at least once inside every scene."],
    "emotionGap": [3,"Two people feeling very different want different things, which pushes them into conflict.","A gap between feelings shows how alone people can be in the same room.","The audience waits for the gap to close or blow up.","thought","Make one character panic while the other calmly makes tea."],
    "emotionIntensity": [3,"A strong feeling pushes a character to act, and actions move the plot.","How strong the feelings run says what the film thinks is worth caring about.","Rising feeling makes the audience brace for where it will burst.","visual","Build the feeling slowly through the scene and peak it on the last line."],
    "emotionalDebt": [3,"Feeling held in builds pressure that has to come out, which sets up a scene.","What people hold back is a theme of repression.","The audience waits for the held-in feeling to burst.","thought","Hold the feeling in for three scenes, then let it out."],
    "emptySpace": [1,"Empty space waits to be filled, so the audience expects someone or something to arrive.","Emptiness can be loneliness or freedom.","The eye goes to empty space waiting for it to change.","visual","Leave a chair empty that someone will sit in later."],
    "energyArc": [3,"Building energy up, dropping it and building again gives the story its rises toward big moments.","Where the energy peaks shows what the film thinks is most important.","A drop after a peak gives the audience a breath, and the next build pulls them back in.","thought","Plan the energy of each scene on a simple chart and make sure the biggest peak is near the end."],
    "enneagramType": [3,"Each type acts from a core fear: a Helper says yes too often, a Challenger pushes too hard, and the plot follows.","Setting types against each other, like a Reformer and an Enthusiast, turns the film's ideas into arguments between people.","Once the audience knows what a type fears, they wait for the scene that forces them to face it.","thought","Put a Peacemaker in a room where everyone demands they pick a side, and let them try not to."],
    "envMotion": [1,"A world in motion (traffic, crowds, waves) keeps the clock running even when the characters stop.","A moving world against still people is a theme of being left behind.","Motion in the background keeps the eye alive between lines.","movement","Let the background slow to stillness before the big line."],
    "escalatingLie": [4,"A lie that grows drives the plot by itself; each scene must make it bigger.","Lies and honesty are the theme.","The audience waits for the lie to come out.","plot","Make each scene force the liar to add one more detail."],
    "exaggeration": [1,"Blowing a problem up bigger than life raises the stakes the plot must deal with.","What a character exaggerates shows what they fear or care about most.","Once things are bigger than life, the audience waits to see if they can grow any bigger.","visual","Make each telling of the same story a little bigger than the last."],
    "exit": [4,"A main character leaving or dying changes everything after it and forces the others to go on without them.","Whether someone walks out or dies shapes what the film says about choice, loss and loyalty.","Hints that a main might leave make the audience watch every scene with them closely, fearing it is the last.","plot","Plant a small warning of the exit two scenes before it happens so it hurts but feels fair."],
    "eyeline": [2,"Where people look tells the audience where the next thing is coming from.","Who looks at whom, and who looks away, is the theme of the relationship.","The audience looks where the characters look.","thought","Have everyone look off screen before cutting to what they see."],
    "faceIntensity": [2,"A face that changes on a beat shows the moment a character takes in news and decides what to do.","How much someone lets show on their face says how much they hide.","A face that snaps to a new expression makes the audience ask what just happened inside.","visual","Hold a calm face through bad news, then let it break on something small."],
    "falseHigh": [4,"A false high or low tricks the audience into thinking the story is over, so the real ending hits harder.","Things seeming fine and then not is a theme about pride or hope.","Surprise reversals snap attention back.","plot","Let the hero win too easily at the midpoint."],
    "featureRate": [3,"How often a main shows up across the season decides how much their story moves forward each episode.","Characters who appear in every hour feel central; those who appear rarely feel like visitors or mysteries.","A main missing for a few hours makes the audience wonder where they went and wait for their return.","plot","Count each main's hours across the season and give the one with the biggest story the most."],
    "feelingEcho": [3,"A returning feeling reminds the audience how far the story has come.","A feeling that means the opposite now shows how much the characters have changed.","When the echo starts, the audience remembers the last time and waits to see what's different.","audio","Bring back the music from an early scene at the end, but slower."],
    "filterHue": [1,"The tint color sets the mood more than it moves the story.","Red feels like danger or love; blue feels cold or sad; green feels sick or strange.","A sudden new tint color warns the audience that the mood has turned.","visual","Shift the tint toward red as the argument heats up."],
    "fireLight": [2,"Firelight flooding a scene shows the fire is growing and becoming the center of the story.","Flickering firelight feels warm and ancient, like stories told around a campfire, or like danger closing in.","Flickering light keeps faces moving between shadow and light, holding attention on them.","visual","Light a fireside confession only by the flickering flames so faces keep slipping in and out of shadow."],
    "fishOutOfWater": [3,"Not fitting in gives the character a clear problem every scene: survive this strange world.","Being out of place is the theme of belonging, and what home really means.","The audience wants to see what new rule they will break next and whether they learn.","thought","Give them one small win in the new world each act, and one big mistake."],
    "fixation": [3,"The thing they cannot stop thinking about drives them toward it, even when it costs them.","A fixation shows what a character thinks will fix their life, and whether it really can.","Each time they glance at it, the audience waits for them to finally grab it or lose it.","visual","Let the fixation pop up somewhere ridiculous, so the audience laughs before the character even notices it."],
    "focus": [2,"Shifting which thing is sharp tells the audience what to notice next, like a hidden clue.","What the film keeps sharp is what it says matters.","When the sharp spot slides to something new, every eye follows it.","visual","Shift the sharpness from a face to a door just before someone knocks."],
    "focusShift": [3,"When a character's attention shifts, the plot shifts with it.","What someone stops caring about is a theme.","The audience's attention follows theirs.","thought","Shift their focus away from their goal at the midpoint."],
    "focusWidth": [2,"What someone is paying attention to decides what they notice and what they miss, and misses drive plots.","Narrow focus against wide focus shows the cost of tunnel vision or the gift of seeing everything.","If the camera follows their focus, the audience notices the thing they are missing in the edge of frame.","visual","Keep the character fixed on one person while the real trouble happens behind them in plain view."],
    "foreshortening": [1,"A huge hand or foot pushed at the camera makes an action feel urgent and close.","Something stretched big near us feels powerful or threatening.","A giant near object grabs the eye instantly, and works well for comic exaggeration.","visual","Shove a pointing finger right at the lens for an accusation."],
    "fourthWall": [2,"A look to the camera lets the character tell us their plan, so we watch for it to work or fail.","Talking to us makes the audience a partner in the character's choices and lies.","When the character glances at us, the audience feels let in and watches for the next secret.","visual","Have them glance at the camera just before their plan goes wrong."],
    "frizz": [1,"Hair getting frizzier through the day shows stress and chaos building up on a character.","Stray, flyaway hair shows a person coming undone, while smooth hair shows them holding it together.","Frizz growing scene by scene makes a quiet visual countdown to the character's breaking point.","visual","Add more frizz to the hero's hair in each scene of the bad day, ending in a comic explosion of hair."],
    "furLag": [1,"Fur that trails behind the body shows how fast a creature is moving, helping action feel quick.","Springy, trailing fur makes a creature feel soft and huggable rather than hard.","Fur catching up after a sudden stop gives a small after-beat that holds attention a moment longer.","movement","Stop the creature suddenly and let its fur keep flopping forward a beat later for a laugh."],
    "furLength": [1,"A character's fur or hair growing or being cut can mark time passing or a change in who they are.","Long, wild hair feels untamed; short, neat hair feels controlled or reset.","Long hair gives the eye something moving to follow as the character turns toward what comes next.","visual","Give the hero a dramatic haircut at the point where they decide to change."],
    "furResponse": [1,"Fur that starts reacting to wind or movement tells us the creature has come alive or the weather has turned.","Fur moving with the body makes a creature feel real and alive, not a stiff toy.","Fur rippling as a creature moves draws the eye to its body and where it is heading.","movement","Keep the creature's fur still while it sleeps, then let it ripple as it wakes and turns."],
    "gazeShift": [1,"Eyes that dart to an object can tip off where the plot is going before anyone speaks.","Looking away or down shows shame or doubt; looking at someone shows connection.","Wherever the eyes dart, the audience's eyes follow.","visual","Have a character's eyes dart to the hidden object every time someone mentions it."],
    "gesture": [1,"A big sweep of the arm can show someone taking charge of a scene and steering where it goes.","Gesture size shows how much a character takes up space in the world.","A gesture right before a word points attention at what is coming.","movement","Give a timid character one huge gesture at the worst possible moment."],
    "gloss": [1,"A mirror-shiny surface can show a reflection that reveals someone or something off-screen.","Shiny polished surfaces feel rich and cold; dull ones feel lived-in and honest.","A glint off a shiny surface catches the eye like a wink, pointing at what the scene wants noticed.","visual","Let a polished table reflect the person sneaking up behind the hero before the hero sees them."],
    "glow": [2,"An object or person that glows on its own marks them as the thing the plot is about to turn on.","Something that shines from within feels magical, holy or dangerous, set apart from the ordinary.","A glowing object is the first place the eye goes, and the audience waits for someone to reach for it.","visual","Make the key object glow faintly in the first scene so the audience spots it long before the characters do."],
    "gravityFeel": [1,"The world feeling heavier as the story goes on shows the characters carrying more weight and trouble.","Floaty movement feels like dreams and freedom; heavy movement feels like duty, age and real consequence.","When something falls with real weight, the audience feels the thud and braces for what it means.","movement","Make the hero float lightly when happy and land with a heavy thud after the bad news."],
    "groupPressure": [3,"Pressure from the group forces one person to give in or stand alone, and either choice moves the story.","One person against many is the clearest picture of conscience versus belonging.","Putting the group on one side of the frame and the person alone on the other makes the audience wait for them to cross.","visual","Stage the group on one side and the hold-out alone on the other, then slowly let one person drift over."],
    "groups": [3,"Splitting the mains into two groups lets the story cut between them and build toward when they meet.","Two groups inside the same company can stand for two sides of the same question.","Cutting between two groups leaves each on a small cliffhanger, pulling the audience back to them.","plot","Split the mains into two groups and have their paths cross once, for a clash or a mix-up."],
    "growth": [3,"An element growing, like a spreading fire or rising water, works as a ticking clock the characters must beat.","Something building out of control shows how small problems become big ones if ignored.","A threat that keeps growing makes the audience check it in every shot, asking how long is left.","visual","Show the rising water in every cutaway so the audience tracks the clock without being told."],
    "gutter": [2,"The gap between panels is where time passes, letting the reader fill in what happened off-panel.","What the gap hides shows what the story trusts the reader to imagine, often the funniest or worst part.","A wide gap makes the reader wonder what happened in between and hurry to the next panel.","thought","Put the crash in the gap between panels and show only the before and after."],
    "hairColor": [1,"Hair going gray or changing color can tell the audience years have passed or a choice was made.","Hair color can tie characters together as family or mark one as different from the rest.","A streak of gray appearing makes the audience wonder what this person went through.","visual","Add a single gray streak after the scene that frightens the hero most."],
    "hairShine": [1,"Hair going from glossy to dull shows a character's health, luck or pride slipping away.","Glossy hair suggests vanity, wealth or youth; dull hair suggests tiredness or not caring anymore.","A bright shine on hair catches the light and the eye whenever the character moves their head.","visual","Make the vain character's hair absurdly glossy, then dull it the moment their pride is hurt."],
    "herdLeader": [3,"Whoever leads the group decides where the group goes, so a change in leader changes the plot.","Who people follow, and why, shows what the film thinks about power and trust.","When the leader's pull weakens, the audience watches for who will step up next.","visual","Give the leader a moment where they turn around and find nobody followed them."],
    "herdMentality": [3,"When a group thinks as one, a single doubter becomes the plot, or gets crushed.","Thinking with the crowd versus thinking alone is the film's question about courage and belonging.","As the shared idea spreads, the audience waits for someone to break from it.","thought","Have the whole group agree with a terrible idea at once, then show the one person who almost objects."],
    "hook": [3,"A signature image comes back at turning points, marking the road.","The repeated image becomes the theme in one picture.","Recognition pulls attention.","visual","Open and close the film on the same image, changed."],
    "hope": [4,"Hope gives the character a reason to keep going, and the audience a reason to hope with them.","Hope against despair is a theme in almost every story.","Hope offered and taken away keeps the audience on the hook.","plot","Give them a reason to hope just before the worst happens."],
    "humiliation": [3,"Losing face makes a character want to win it back, which drives their next choices.","Whether they earned it decides if the film is about justice or cruelty.","The audience waits for the comeback, or dreads the next fall.","plot","Fill the room with witnesses at the exact moment they fall."],
    "impacts": [2,"Hits and crashes mark the beats of a fight or chase, each one pushing the action forward.","How hard and how often things collide shows how violent or clumsy the world is.","A run of crashes builds a rhythm the audience follows, waiting for the biggest hit at the end.","movement","Build a run of small bumps and knocks, then pay it off with one big crash for the laugh."],
    "intExt": [2,"Going outside opens the story to the world; coming inside closes it into a room where people must face each other.","Inside against outside is safety against danger, private against public.","Stepping out of a door is a visual promise that the story is going somewhere.","visual","Hold the characters inside until the turn, then send them out."],
    "intercut": [4,"Cutting between two lines of action makes them race toward each other.","Two stories side by side comment on each other.","Cutting away at the peak makes the audience wait to come back.","plot","Cut away from each line at its most tense moment."],
    "irony": [3,"When the opposite of what someone expects comes true, the plot turns on them.","Irony is how a film shows that people's plans and the world rarely line up.","When the audience knows more than the character, they wait for the moment the truth bites.","thought","Let the audience see the trap a scene before the character walks into it."],
    "jokeCarrier": [2,"Who gets the laughs tells us who drives the scene and whose plan is in play.","Whether the funny one knows it shows whether the film laughs with them or at them.","The audience starts watching the funny one, waiting for the next thing they do.","visual","Hand the laugh to the straight one once, at the moment it matters most."],
    "key": [1,"Moving the main light from the front to the side or below tells the audience the scene has turned darker or stranger.","Light from the front feels honest; light from below or behind makes the same face feel hidden or dangerous.","A face lit from one side leaves half in shadow, and the audience waits to see the hidden half.","visual","Light a character from the front all film, then swing the light to the side the moment they start lying."],
    "laughsPerMinute": [1,"Steady laughs keep the audience happy enough to follow the plot through its slower stretches.","Fewer laughs as the story darkens shows the film taking its own problem seriously.","A rhythm of laughs trains the audience to expect the next one, and they keep watching for it.","audio","Drop the laughs to almost none just before the big turn, then bring them back."],
    "layoutOpen": [2,"A cramped room forces conflict; an open one lets people avoid each other.","Cramped against open is trapped against free.","When a space closes in, the audience feels the pressure build.","visual","Shrink the space a little in every scene of the second act."],
    "leadPart": [1,"Which part moves first shows what the character wants: eyes to a door, hips toward a person.","Leading with the head shows thinking; leading with the hips shows desire or instinct.","When the eyes lead, the audience follows them to where the next beat is.","movement","Let the eyes go to the exit a full second before the body turns to leave."],
    "lensLength": [1,"A wide lens shows the whole room and what is coming; a long lens shuts it out.","Wide feels open and exposed; long squeezes people together, close or trapped.","A wide view gives the eye room to find what is approaching from the back.","visual","Use a wide lens when the danger is in the background."],
    "lightChange": [3,"The light changing (a lamp switched off, the sun going down) marks time and turns the scene.","Light changing is hope or threat arriving.","A change in light pulls every eye.","visual","Change the light at the moment the feeling turns."],
    "lightCount": [1,"Going from many lights to a single lamp shrinks the world down to the one thing that matters now.","A room lit by many sources feels busy and social; one source feels lonely and focused.","When lights go out one by one, the audience counts down with them and braces for darkness.","visual","Turn off one lamp in the room each time a guest leaves, until one light remains."],
    "lightShape": [1,"Stripes from window blinds or leaf shadows sliding across a face mark that time is passing or danger is near.","Bars of shadow from blinds can make a free person look caged, without saying so.","Moving patterns of light across a wall draw the eye along with them toward the next thing in the room.","visual","Cast blind-shaped stripes across the suspect's face only after the detective starts to doubt them."],
    "lighting": [1,"Changing the whole look of the room, from dusk to hard light, tells the audience a new chapter has started.","The film's overall light, soft dusk or harsh moonlight, sets what kind of world this is.","A sudden switch in the room's light makes the audience ask what just changed, carrying them into the next beat.","visual","Snap the room from warm lamps to hard overhead light at the exact line where the argument starts."],
    "lightingLens": [2,"Changing where the light falls, how hard and warm it is, maps out how the scene's mood moves from start to end.","The light's direction, warmth and darkness together tell the audience what this world feels like to live in.","Light leads the eye: the audience looks first at what is brightest and waits for darker corners to be lit.","visual","Plan the light for the start and end of each scene, then make one clear change at the turn."],
    "lightingMood": [1,"Light shifting on the turn marks the moment the story changes direction.","Dark and light show hope and fear across the film.","A change in the light makes the audience feel something changed before they see why.","visual","Let the light dim slowly as the bad news is told."],
    "lineWeight": [1,"Outlines getting heavier around a character can show them becoming more solid, certain or important.","Thick, bold outlines feel playful and loud; thin or missing ones feel delicate and real.","Heavy outlines make shapes pop off the background, so the eye jumps straight to the outlined figure.","visual","Draw a thick outline only around the one character the gag hinges on so the eye finds them first."],
    "lipSync": [1,"Mouth shapes make the speech believable but do not change what happens.","Careful mouths feel real and sincere; loose ones feel playful and stylized.","A mouth that matches the words keeps attention on what is said, not how it is drawn.","visual","Open the mouth wide on the loudest word of the line."],
    "listenerBody": [2,"The listener's reaction shows whether the speaker's words worked, telling the audience what happens next.","How someone listens shows if they care, agree or are already gone.","Cutting to the listener makes the audience read their body for the real answer, and often the laugh.","visual","Keep the listener in the edge of the frame, slowly leaning away as the speaker keeps talking."],
    "look": [2,"A change in a character's appearance shows that something in their life has changed.","How someone looks shows who they are trying to be.","A striking or wrong-looking outfit makes the audience wonder what it means, or laugh at it.","visual","Change the hero's look once, right after their big choice."],
    "mainCost": [2,"Money on someone's back says what they can do and what they stand to lose; a drop in cost marks a fall.","Cheap against expensive is how a film shows class, greed or humility.","A sudden change in what someone can afford is a plot question the audience wants answered.","visual","Dress them one step richer or poorer after each turn of fortune."],
    "mainCoverage": [1,"Covering up or showing more marks someone opening up or closing off, which predicts what they will risk next.","How much a character hides of themselves is a theme of trust and shame.","A change in how much is shown draws the eye and makes the audience wonder what changed inside.","visual","Uncover a little each time the character lets someone in."],
    "mainEra": [1,"Clothes from another time say the character belongs somewhere else, which sets up a fish-out-of-water plot or a return home.","The era of the clothes can carry the film's argument about past and present.","An out-of-time outfit makes the audience ask why they dress that way.","visual","Let the era of their clothes move toward today as they let go of the past."],
    "mainFit": [1,"A change in how clothes fit can show a character growing, shrinking or pretending.","Tight clothes feel controlled; baggy ones feel careless or hiding.","Clothes that clearly do not fit make the audience wonder why, or laugh.","visual","Put the hero in a suit that is too big when they first try to be the boss."],
    "mainFormality": [2,"Dressing up or down shows a big event coming or a character's status changing.","How formal someone dresses shows how they want to be seen.","Someone in the wrong clothes for the room is a ready-made joke or tension.","visual","Send the hero to a formal party in sleepwear."],
    "mainFunction": [2,"Clothes doing a job (disguise, uniform, armor) open doors in the plot that would otherwise be shut.","A uniform or disguise asks who the person really is.","A disguise makes the audience wait for it to be found out.","plot","Put a character in a disguise one scene before someone who could see through it arrives."],
    "mainSetMatch": [1,"A character who clashes with the room is about to be thrown out of it or change it.","Belonging against standing out is a theme in the frame.","The one person who does not match the room pulls every eye.","visual","Dress the main character to clash with the room they are trying to win."],
    "mainUtility": [2,"Clothes made for a job say what that person is about to do: armor before a fight, boots before a journey.","Looks against function is a theme of appearance against substance.","Seeing someone dress for a task tells the audience the task is coming, and they wait for it.","visual","Show the character putting on the clothes for the coming scene."],
    "mainWear": [1,"Wear and tear on clothes keeps score of what the character has been through, so the audience feels the journey.","Damage that builds up is the theme of cost and endurance.","A new tear or stain makes the audience ask what just happened.","visual","Let the same outfit get a little more worn each act."],
    "mains": [4,"Choosing two to four main characters decides whose goals drive the hour and whose problems we follow.","Who gets to be a main character tells the audience whose lives the film thinks matter.","Following a small group means each one's next move matters, and the audience wants to see them all through.","plot","Pick two to four mains and give each one a goal they chase all hour."],
    "mindset": [3,"A mind that will not change keeps hitting the same wall until pressure forces a crack.","Fixed versus open is the film's question about whether people can learn.","The more a belief is challenged, the more the audience waits for it to bend or break.","thought","Have a stubborn character win an argument with logic that is clearly, comically wrong."],
    "misdirection": [3,"Pointing the audience one way and paying off another makes the plot feel alive.","Misdirection is a theme of appearances.","Surprise snaps attention.","thought","Lead the audience to expect the obvious punchline, then hit them with another."],
    "misunderstanding": [4,"A misunderstanding sends people off in the wrong direction, which makes plot.","Not listening to each other is a theme.","The audience knows the truth and waits for the moment it clears up.","plot","Let the audience see the mistake happen."],
    "mixArc": [3,"Being stuck together changes the characters, and changed characters make new choices.","Whether the group makes them better or worse is the film's view of people.","The audience watches for the first sign that someone has changed.","thought","Let the straight one learn something from the funny one, not the other way round."],
    "mixLaughs": [1,"Laughs that come from who is in the room keep the scene alive while the plot sets up.","Laughs from the people, not jokes, say these people are funny because of who they are.","The audience looks forward to the next time these people share a room.","thought","Write the scene with no jokes and let the mix of people make it funny."],
    "mixPlot": [4,"When these people together cause a snag or a collapse, the plot changes course.","Who gets blamed shows whether the film believes in fairness.","The audience wants to know who will get blamed and what breaks next.","plot","Have the group cause the problem and blame the one person who didn't."],
    "mixedFeelings": [2,"Feeling two things at once makes a character hesitate, and which feeling wins decides what they do.","Mixed feelings show that real moments are never just one thing.","The audience watches to see which feeling will win.","visual","Let a smile flicker through tears at the moment of loss."],
    "motifShape": [2,"A repeated image growing bigger or brighter each time it returns shows the story building toward it.","How the motif rises or falls traces the rise or fall of what it stands for.","As the motif grows with each return, the audience expects it to peak and watches for that moment.","visual","Show the moon a little bigger each time it appears, fullest on the night of the climax."],
    "motionBlur": [1,"Blur colors how fast things feel but rarely changes what happens.","Smeared motion feels frantic and dreamy; crisp motion feels nervous and sharp.","Heavy blur on a fast move makes the eye feel the speed and catch the stop.","visual","Keep motion crisp in the fight, and smear it only when the hero is dazed."],
    "moveFollows": [2,"Following a person or object tells the audience whose path matters to the plot.","What the camera chases is what the film cares about.","When the camera leaves a person to follow an object, the audience knows the object matters.","movement","Let the camera drop the hero and follow the stolen wallet instead."],
    "moveOn": [1,"Starting a move on a line or action ties the camera to the moment that drives the scene.","A move that starts on a breath feels felt; one on an action feels driven.","A move that kicks off on a cue tells the audience that cue mattered.","movement","Start a slow push in on the exact word where the character gives themselves away."],
    "moveOnLine": [1,"A step on the key word pushes the line home and marks it as the turn of the scene.","Moving against the words shows what the character feels versus what they say.","Freezing after a line makes the audience wait for the reaction.","movement","Have the character step forward on the key word, then freeze for a beat after it."],
    "moveSpeed": [1,"A fast camera move rushes us toward an event; a slow one builds dread.","Slow moves feel thoughtful or creeping; fast moves feel urgent or comic.","A slow push in makes the audience feel something is coming.","movement","Creep the camera in slowly through the whole speech, then stop on the last word."],
    "moveTemper": [1,"A calm camera tells us things are in hand; a jumpy one warns that they are slipping.","The camera's attitude shows how the film itself feels about what it sees.","When the camera's mood changes, the audience senses the scene has turned.","visual","Keep the camera calm all scene, then let it lurch once at the turn."],
    "moveToVolume": [1,"Tying camera moves to loud or soft speech links the camera to the scene's heat.","Moving on soft lines says the quiet words matter most.","A camera that moves on a whisper makes the audience lean in.","audio","Move the camera only when someone whispers, and freeze it during shouting."],
    "movementAmount": [1,"More movement makes a scene feel urgent, like the plot is racing toward something.","Stillness against motion shows calm against panic.","Motion catches the eye, and a sudden stop makes the audience wonder what happened.","movement","Have everyone stop moving at once just before the key line."],
    "music": [2,"Music arriving tells the audience the scene has become important.","A tune tied to a person or idea brings the theme back each time it plays.","Music starting or stopping is one of the strongest audio cues there is.","audio","Start the music on the turn, not at the top of the scene."],
    "musicCue": [2,"The score tells the audience how to feel about where the plot is going.","A theme in the music follows the theme of the film.","A score change moves attention to what it plays under.","audio","Bring the main tune back only at turning points."],
    "noMusic": [2,"Pulling the music out makes the next moment feel exposed and real.","Silence where music was is a theme of loss or truth.","The sudden absence of music makes the audience hold their breath.","audio","Cut the music on the most important line."],
    "objectEnter": [2,"Something coming into the frame is something entering the story.","What arrives in the frame and what leaves it tells you what the film gains and loses.","Anything entering the frame takes the eye.","movement","Have the object enter just as the line about it ends."],
    "objectKind": [2,"An object can be the thing everyone wants: the plot follows it.","An object can stand for the theme (the ring, the letter, the key).","A new object in the frame becomes a question.","visual","Introduce the object with a reaction shot, not on its own."],
    "objectPath": [3,"An object lifted, dropped or passed hand to hand is often the plot changing hands.","Who holds an object and who gives it away shows trust, power and loss.","A thing in motion pulls the eye, and a drop or slide sets up a gag or a shock.","movement","Pass the key object from one hand to another at the moment power shifts."],
    "objectSpeed": [1,"An object racing or crawling sets how urgent its arrival will be.","A slow fall feels like fate; a fast one feels like an accident.","A thing speeding toward someone makes the audience brace for impact.","movement","Slow a falling glass almost to a stop, then let it smash."],
    "oddOneOut": [2,"The one who doesn't fit stirs up trouble or sees what the group can't.","Not fitting in is the theme of belonging and the price of joining.","The audience wonders whether the group will throw them out or follow them.","visual","End the scene with the group copying the odd one out."],
    "operatorFeel": [1,"A camera that drifts a little, as if handheld by a person, makes the story feel like it is happening right now.","Small human wobbles feel real and close; perfectly smooth moves feel cold or distant.","A slightly late camera catching up to the action makes the audience feel they are chasing it too.","movement","Have the camera be a beat late to find the person who just spoke, like a real operator surprised."],
    "overlap": [1,"Hair and cloth still moving after the body stops show how hard the move really was.","Loose parts that lag behind make characters feel heavy, real and alive.","Something still swinging after the stop keeps the eye on that character a moment longer.","movement","Let a hat or tie keep flapping a beat after the character freezes in shock."],
    "overshoot": [1,"A body that overshoots and bounces back sells the force of the action that just happened.","A wobble after a stop shows a world that is soft and alive rather than stiff.","The little bounce after a stop holds the eye a beat longer, which is perfect for a punchline.","movement","Let a character skid past their mark and wobble back for a laugh."],
    "pace": [2,"Speeding up the lines speeds up the scene toward its end.","Fast against slow talk shows who is in control.","A change in pace makes the audience listen differently.","audio","Speed up the talking as an argument nears its turn."],
    "pageTurn": [4,"Placing the reveal on the next page makes the reader turn to find out what happened.","What waits on the next page shows what the story thinks is worth holding back.","Ending a page on a question or cliffhanger forces the reader to turn and keep going.","plot","End the right-hand page on the door opening, and show who is behind it on the next page."],
    "palette": [1,"A new main color arriving in the shots marks a new place, person or chapter taking over.","The film's main colors stand for its ideas, such as red for danger or blue for loneliness.","A single shot of a clashing color jumps out and makes the audience look for what it means.","visual","Keep every shot in soft blues, then let the rival walk in wearing bright orange."],
    "panelBreak": [1,"A figure bursting out of the panel border shows the action breaking out of the ordinary.","Breaking the frame shows a character too big, wild or important to be contained.","A figure crossing the border leaps out at the reader and pulls their eye toward the next panel.","visual","Let the character's fist or foot break out of the panel border at the biggest hit, or a pratfall."],
    "panelCount": [2,"More panels on a strip stretch a moment out; fewer panels jump the story forward faster.","Many small panels feel busy and detailed; few big panels feel bold and important.","A long strip of panels makes the reader race along to see how it ends, often for the punchline.","visual","Use three small panels to set up a joke and one last panel for the punchline."],
    "panelSize": [2,"Panels getting bigger mark the story arriving at its big moment.","Big panels show what matters most; small ones are the steps along the way.","A suddenly large panel stops the reader's eye and holds it on the key image.","visual","Use small panels for the buildup and one large panel for the reveal or punchline."],
    "payoffDistance": [3,"A long gap between setup and payoff ties distant scenes together so the whole film feels like it is going somewhere.","A late payoff says nothing in this world is wasted.","The audience remembers the setup and waits.","thought","Put at least one setup more than half the film before its payoff."],
    "pedal": [1,"Holding one thing steady while everything else changes gives the story a fixed point the audience can measure change against.","A thing that stays the same while the world shifts shows what lasts, or what refuses to change.","The audience keeps checking the steady thing, waiting for the moment it finally changes too.","thought","Keep the same clock ticking in every scene, and stop it at the turning point."],
    "peopleCount": [2,"Adding or removing people changes who can help, block or witness what happens.","A crowd versus one person alone shows belonging against loneliness.","A packed frame keeps the eye searching; one lonely figure holds it still.","visual","Empty the room one person at a time until the hero is alone."],
    "personalSpace": [2,"Closing or opening the space between two people shows where their relationship is heading.","Distance between people is the theme of closeness and loneliness.","The audience watches the gap, waiting for someone to cross it.","movement","Make them cross the room to close the space only at the end."],
    "perspectiveWidth": [3,"Someone who only weighs their own good makes different choices than someone weighing the whole group, and the plot follows.","A circle that grows from self to world is one of the clearest ways to show a character becoming better.","When the circle starts shrinking, the audience waits for who will be left out and hurt.","thought","Give them a choice where helping family means letting down a stranger they just met."],
    "phraseScheme": [2,"Grouping shots into steady runs, like fours, makes the story feel orderly until a run breaks short at a turn.","A steady pattern of shots feels calm and safe; a broken pattern feels like something went wrong.","Once the audience feels the pattern, they expect the next run, and a break surprises them.","visual","Cut a scene in steady groups of four shots, then cut one group short right at the punchline."],
    "physicalComedy": [2,"A fall or a mess often breaks something the plot needed, which starts the next problem.","Bodies failing in front of people make a theme of pride and how easily it breaks.","A slow build up to a fall makes the audience wait for the crash they know is coming.","movement","Show the banana peel early, then make them wait for the slip."],
    "plotProgress": [5,"Closer or further from the goal is the plot's own clock.","Progress and setbacks show what the theme costs.","Every step forward or back keeps the audience counting.","plot","Knock them back right after their biggest step forward."],
    "plotSecret": [4,"A secret about to come out drives scene after scene.","Secrets are a theme of trust and shame.","The audience waits for the secret to come out.","plot","Let the secret almost come out once per act."],
    "plotTouch": [4,"When a side story crosses the main plot it can change the main plot's direction or speed it up.","Stories that join show that separate lives are tied together, whether the characters like it or not.","Two stories running apart make the audience wait for the moment they collide.","plot","Have a side character's small problem crash into the main plot at the worst possible moment."],
    "plotWant": [5,"Want against need is the engine of the plot: chasing the want drives the action, finding the need ends it.","The gap between want and need is usually the theme.","The audience waits for the character to see what they need.","plot","Let them get what they want and find it is wrong."],
    "plotWeight": [3,"The more weight a scene puts on this character's own story, the more their goal moves forward or slips.","Who gets whole scenes to themselves tells the audience whose struggle the film cares about.","When the stakes grow from pride toward a livelihood or a life, the audience needs to see the next scene with them.","plot","Raise what they stand to lose one notch each time this character gets a scene of their own."],
    "poseRate": [1,"Strong held poses make each line of dialogue clear, so the point of the scene lands.","How many poses a character strikes shows if they are calm or bursting with feeling.","Each new pose is a fresh thing to look at, keeping attention on the speaker.","movement","Give the punchline its own held pose, and hold it a beat longer."],
    "posture": [1,"A body opening or closing shows a character letting someone in or shutting them out.","Open and closed bodies show who feels safe and who feels threatened.","A shift in posture tells the audience something changed before any words do.","movement","Have a character slowly uncross their arms during the scene as they start to agree."],
    "postureChanges": [1,"Turning away or opening up shows a decision being made before it is said.","Closing up or opening up tells the story of trust between people.","A shift in posture catches the eye and makes the audience read what it means.","movement","Have them fold their arms when they lie and unfold them when they give in."],
    "pov": [3,"Seeing through someone's eyes puts us in their plot: we want what they want.","Whose eyes we borrow is whose side we are on.","A point-of-view shot makes the audience search the frame the way the character would.","thought","Switch to the villain's eyes once, just before they act."],
    "povSwitch": [4,"Switching whose story each scene tells lets the plot show things one character can't know.","Whose stories we follow decides whose side we are on and whose view of the world we share.","Switching to a new person makes the audience wonder what they know that the others don't.","thought","Tell one scene from the villain's side, then go back to the hero knowing more than they do."],
    "practicalInFrame": [2,"A lamp, screen or fire we can see can be switched on or off by a character, making light part of the action.","A visible flame or glowing screen shows what the characters gather around and depend on.","A light we can see in the shot invites the audience to watch it, waiting for it to flicker or go out.","visual","Put a lamp in the shot early and have a character switch it off at the turn of the scene; for a laugh, have it flick back on by itself."],
    "propBusiness": [1,"Hands busy with a task show feeling without words, and the task going wrong can start the next beat.","What someone does with their hands shows their life and what they care about.","A task that starts going wrong makes the audience watch it as closely as the talk, and laugh.","visual","Let the chore get worse as the conversation gets worse, until the pot boils over."],
    "props": [3,"A prop handed over, lost or broken can move the whole plot.","A prop that keeps returning carries the theme each time.","A prop the camera notices becomes a promise the audience waits on.","movement","Plant the prop in act one; use it in act three."],
    "psychOut": [3,"A fake shift that snaps back tricks the audience, making the real shift, when it comes, hit harder.","Fake-outs show how quickly hope or fear can switch, and how we fool ourselves.","After one fake-out, the audience distrusts every shift and watches closely to see if the next one is real.","thought","Cut to the hero suddenly in a beach chair, then snap back to the office for the laugh."],
    "rackFocus": [2,"Pulling focus from one thing to another is a sentence: this, and now that.","What goes soft and what goes sharp shows what matters.","A focus pull drags attention from one place to another in a single move.","visual","Pull focus from a face to the thing it is afraid of."],
    "rangeChanges": [1,"Frequent jumps between quiet and loud make a scene feel unstable, like something is about to give.","How often someone swings in volume shows how steady or shaken they are inside.","Changes that come at random keep the audience listening for the next jump.","audio","Alternate quiet and loud lines in a fight, then break the pattern with silence."],
    "relapse": [4,"Slipping back undoes progress and sets up a bigger fall or a harder second try.","A relapse says change is not a straight line, and the old self keeps calling.","Once they slip, the audience worries about whether they will climb back, and when.","plot","Bring back an old friend right when the character is doing well, and let them say yes too fast."],
    "renderStyle": [1,"A shift from realistic to cartoon-like or painted pictures can mark a dream, a memory or a story inside the story.","How real the picture looks tells the audience how seriously to take what they are seeing.","When the look of the picture suddenly changes, the audience knows something has shifted and watches to find out what.","visual","Switch to a flat cartoon look for one daydream, then snap back to real for the punchline."],
    "repeatInFrame": [1,"Rows of the same thing set up a pattern that the plot can break.","Repetition shows sameness, order or a world that crushes the individual.","The eye scans a pattern for the odd one out, which is a ready-made gag.","visual","Fill the frame with identical desks and make one of them wrong."],
    "repetition": [2,"An image coming back again and again, changing a little each time, marks how far the story has moved.","A repeated image becomes a symbol, and its changes show what has changed in the characters.","After a few repeats the audience expects the image back, so its next return, changed, lands harder.","visual","Show the same breakfast shot three times, the same each time, then a fourth time with one chair empty."],
    "resistance": [3,"Every refusal to change delays the ending and forces the story to push harder on the character.","How hard someone fights growing shows how much the old self costs to give up.","The audience waits for the refusal to crack, and laughs at each new way the character dodges.","thought","Have the character double down with a bigger excuse every time someone points out the obvious."],
    "reveal": [5,"When the audience learns things decides the shape of the whole plot.","What a film hides and reveals is how it argues its theme.","A held-back answer is the strongest pull a film has.","plot","Reveal the answer one scene after the audience starts to guess it."],
    "rim": [1,"A thin line of light around one figure marks them out as the one the next moment is about.","An outline of light around someone can make them feel special, holy or apart from everyone else.","The bright edge separates a figure from the dark background, so the eye goes to them and stays there.","visual","Give only the hero a glowing outline in the crowd scene, then take it away when they fail."],
    "ruleOfThree": [2,"Two the same and one different is a tiny plot with a twist.","The third beat shows what breaks the pattern.","The pattern makes the audience expect, and the third breaks it.","thought","Set up two the same, then make the third the turn."],
    "runningGag": [2,"A running gag changes a little each time, tracking how the story has changed.","What keeps repeating is what the film keeps thinking about.","The audience waits for the next time it comes back.","thought","Let the running gag stop being funny at the low point."],
    "saturation": [1,"Colors draining out of the picture tell the audience joy is leaving the story, and filling back in shows it returning.","Bright full color feels alive and silly; washed-out color feels tired, sad or remembered.","Color slowly returning to a gray world makes the audience watch for what brought it back.","visual","Drain the color a little in every scene after the loss, then let one bright color return at the end."],
    "scale": [2,"A huge place makes people small and the task big; a small place makes every person matter.","Scale is a theme of power and helplessness.","Cutting from a small place to a huge one tells the audience the stakes just grew.","visual","Open up the scale of the place when the stakes rise."],
    "scatter": [1,"Debris or crowds spreading across the scene show what has happened, such as a blast or an event drawing people.","Scattered leaves or litter show how lived-in, neglected or chaotic a place is.","A trail of scattered things leads the eye like breadcrumbs toward where the action is.","visual","Lay a trail of fallen leaves or dropped items leading right to the hiding spot."],
    "sceneEntry": [3,"Entering a scene late (in the middle of something) makes the plot feel like it is already running.","How scenes begin sets the film's rhythm.","Coming in late makes the audience work to catch up.","visual","Start each scene as late as you can."],
    "sceneLength": [2,"Long scenes let a situation build slowly; short scenes push the story along quickly.","Long scenes feel patient and intimate; short ones feel busy and restless.","A scene that runs longer than the ones before makes the audience feel this one matters.","thought","Keep most scenes short, then let one key scene run twice as long."],
    "sceneRate": [3,"Changing scenes more often makes the story feel like it is racing; fewer changes let it slow and deepen.","Fast scene changes feel like a busy, scattered life; slow ones feel calm and thoughtful.","Speeding up scene changes near the end makes the audience feel the story rushing toward its climax.","plot","Cut between scenes faster and faster in the last act, then slow down for the final scene."],
    "sceneShapes": [1,"A frame that changes from empty to busy can signal that the story is crowding in on someone.","Big shapes and small ones show who or what dominates the world of the film.","A single big shape pulls the eye straight to it and makes the audience wonder what it means.","visual","Let one big shape, like a doorway or a person, fill the frame right before the turn."],
    "setBrightness": [1,"Rooms getting darker or brighter across the film track how the story is going.","Dark rooms feel heavy and secret; bright ones feel open and hopeful.","A shift in brightness tells the audience the mood has changed before anyone says it.","visual","Make each set a little darker as the hero gets into deeper trouble."],
    "setDepth": [1,"Deep rooms behind people let something arrive from the back before anyone notices.","A flat wall feels trapped; rooms beyond rooms feel like a wider world.","Layers behind the actors give the eye somewhere to look for what comes next.","visual","Stage a background character sneaking through the far room during the conversation."],
    "setLayout": [2,"Where the doors, windows and walls are decides who can enter, leave, hide or overhear.","Layout is a map of power: who sits at the head, who stands at the door.","A door left open or a corner out of sight makes the audience watch it.","visual","Show the exit early, then block it at the climax."],
    "setLines": [1,"The shape of the room sets the mood more than it moves the story.","Soft curves feel warm and safe; sharp lines feel cold, strict or modern.","Sharp lines lead the eye toward a point, while curves let it drift.","visual","Put the villain's office in hard straight lines and the family home in curves."],
    "setMaterial": [1,"What the room is built from tells us where we are, not what will happen.","Rough wood against polished marble shows poor against rich, old against new.","A change of material from scene to scene tells the audience they have moved worlds.","visual","Move the hero from rough wood rooms into polished stone ones as they rise."],
    "setStyle": [1,"Where and when the place comes from sets the rules of what can happen.","The style of the room shows the values of the people in it.","A room that does not fit its people makes the audience ask why.","visual","Show the room's style change after the person who owns it changes."],
    "setUpkeep": [1,"A place falling apart marks time passing and things getting worse.","Upkeep is a theme of care and neglect.","Damage that was not there before makes the audience ask what happened.","visual","Let the home decay as the family drifts apart."],
    "setting": [3,"The place decides what can happen: a desert means thirst, a city means strangers, a ship means no escape.","The landscape is often the theme made physical (isolation, freedom, being trapped).","A new place is a new set of possibilities, so the audience scans it for what will happen here.","visual","Move each act to a place with less room to escape."],
    "settingMood": [1,"A place that feels wrong warns the audience something will go wrong there.","A place that fights the feeling, like a sunny funeral, shows life going on regardless.","A gloomy or cozy place sets up what the audience expects, so they watch for it to change.","visual","Put the saddest scene in the happiest place."],
    "settleTime": [1,"How long things wobble after a hit decides when the story can move on to the next beat.","Things that settle fast feel controlled; things that keep wobbling feel unstable and out of hand.","A long wobble keeps the audience watching, waiting to see if the thing will fall after all.","movement","Make the stacked dishes wobble a beat too long before they finally fall, or don't."],
    "shotDuration": [2,"Holding a shot longer than expected makes the audience feel something is about to happen.","Long holds give weight; short ones keep things light.","A long hold stretches attention on one thing; past a point the audience starts looking for what is wrong.","visual","Hold just long enough to make them uneasy, then cut."],
    "shotSize": [2,"Getting closer as a scene goes on tells the audience we are heading toward the heart of it.","Who gets close-ups is who the film thinks matters.","A cut in close forces the audience onto one face or thing: it now holds attention.","visual","Move one size closer each time the stakes rise in a scene."],
    "silence": [3,"A silence after a line tells the audience something has just changed.","What people cannot say is often the theme.","Silence pulls attention to faces and waits for the next sound.","audio","Leave a beat of silence after the most important line in the scene."],
    "skinColorTruth": [1,"How true the skin looks colors the moment without moving the story.","Faces tinted by the scene feel swallowed by their world; true skin feels human and honest.","When faces return to true color, the eye settles back on the people.","visual","Let faces turn the tint of the scene when the hero is lost, and true again when they find themselves."],
    "skinLight": [1,"Skin that glows warmly as if lit from inside can show a character coming back to life or falling in love.","Warm, living skin feels human; skin with no glow looks waxy, sick or not quite alive.","When a face starts to glow with warmth, the audience feels the character waking up and watches for what they do.","visual","Give a sick character's skin no warm glow, then let the warmth return in the scene where they recover."],
    "softness": [1,"Shadows going from soft to sharp-edged signal that things have stopped being gentle.","Soft shadows feel forgiving and dreamy; sharp ones feel cold, exact and unforgiving.","A sharp shadow on the wall gives the eye a crisp shape to follow, often to where the threat stands.","visual","Use soft light for the first date and hard, sharp shadows for the breakup in the same room."],
    "soundDensity": [1,"Sound layers building up push a scene toward its peak; sudden thinning marks a turn.","A crowded soundscape can show chaos; a sparse one shows loneliness or calm.","When layers drop out, the audience listens harder for what is left.","audio","Build the sound layers up through the scene, then cut to one sound when the turn hits."],
    "soundDesign": [2,"A sound off screen (a knock, a siren) brings the next event into the scene before we see it.","The sounds of a world say what kind of world it is.","An off-screen sound makes the audience look for its source.","audio","Let the audience hear the danger before they see it."],
    "soundLettering": [1,"A big drawn sound word marks the moment something happens, like a crash or a door slam.","The style of the sound words, clean or wild, sets how loud and playful the world feels.","A huge sound word grabs the eye first and makes the reader look for what made the noise.","visual","Draw a tiny 'boink' for what should have been a huge crash to get a laugh."],
    "soundToCut": [2,"Sound that leads into the next scene pulls the audience forward across the cut.","Sound tying scenes together ties their ideas.","Hearing the next scene first makes the audience want to see it.","audio","Start the next scene's sound a second before the cut."],
    "spacing": [1,"How a move eases in and out sets whether an action feels careful, lazy or sudden.","Smooth curves feel graceful and safe; snaps feel sharp, nervous or funny.","A move that snaps after a slow start jolts attention, the classic setup for a cartoon gag.","movement","Start a reach slowly, then snap it to the end for a comic grab."],
    "specificity": [1,"A precise detail can return later as a clue or a payoff the plot needs.","Oddly specific details make a world feel lived in and show what people care about.","A strange detail sticks in the audience's head, and they wait for it to come back.","visual","Name the exact thing instead of the general one, and bring it back once later."],
    "speedRamp": [2,"Slowing time stretches the moment before an impact, so the audience feels the stakes.","Slow motion makes a moment feel like memory or fate.","A change in time speed grabs attention instantly.","visual","Ramp to slow motion on the last second before a choice."],
    "splash": [2,"A splash shows something landed, fell or was thrown, marking an action that the story reacts to.","A big messy splash breaks a moment of dignity and shows the world isn't under anyone's control.","A splash is a sudden burst of motion that grabs attention and makes the audience look for who caused it.","movement","Have the proud character fall in the fountain with a huge splash that soaks the onlookers too."],
    "squash": [1,"Squashing and stretching a body shows impact and effort so a hit or a jump lands.","How rubbery the world is decides how cartoonish and comic the film feels.","A big stretch before a move warns the eye that something fast is coming.","movement","Squash a character flat on landing, then stretch them tall in surprise."],
    "stakes": [5,"What someone stands to lose is why the plot matters.","What a film puts at stake is what it believes is precious.","Rising stakes are the main reason audiences keep watching.","plot","Raise what they could lose at the end of every act."],
    "statusGap": [3,"A big gap in rank sets up a fall or a flip that the plot can turn on.","Status jokes show who has power and how thin it really is.","The audience waits for the high one to fall or the low one to rise.","thought","Let the servant end the scene in charge."],
    "stepping": [1,"How many frames each drawing holds sets how smooth or jerky the motion feels, not where the story goes.","Smooth motion feels real and gentle; choppier motion feels handmade, punchy or comic.","Switching from smooth to choppy motion makes a moment pop out of the flow.","visual","Animate the frantic panic beat in a choppier rate than the calm around it."],
    "stillness": [1,"A character going still signals that something just landed and the scene has turned.","Stillness can show power, fear or shock, depending on who is still and when.","When someone stops moving, the audience stops too and waits for what breaks the stillness.","movement","Freeze a character completely after bad news while everyone else keeps moving around them."],
    "straightMan": [1,"The calm one keeps the plot on track while madness happens around them.","The straight one stands in for us, showing how strange the world has become.","The audience waits for the moment the calm one finally loses it.","visual","Keep them calm through everything, then let one tiny thing break them."],
    "subtext": [3,"What people mean but do not say is often the real plot.","The gap between words and meaning is a theme of honesty.","Subtext makes the audience work out what is really happening, so they stay involved.","thought","Write the scene so nobody says what they want."],
    "subversion": [2,"Breaking a familiar movie moment sends the plot somewhere the audience did not plan for.","Breaking the cliche says real life does not work the way movies promise.","Once a cliche is broken, the audience stops trusting what comes next and watches closely.","thought","Set up the big romantic speech in full, then have the other person not hear it."],
    "temperature": [3,"How bodies behave before anyone speaks tells the audience a fight or a hug is coming.","Cold or hot rooms show the relationships under the words.","A tense room makes the audience wait for the first word to break it.","thought","Start the scene with nobody looking at each other, then have one person speak."],
    "tensionCurve": [5,"Tension rising and falling is the plot's heartbeat.","Where the tension peaks is where the theme is tested.","Rising tension holds attention; falling tension lets it rest.","plot","Never let tension fall all the way until the end."],
    "textDensity": [1,"Fewer words per panel speed the reader along; more words slow them down to take in the moment.","Heavy text feels talky and thoughtful; silent panels feel tense or let a picture speak.","A panel with no words after many wordy ones makes the reader stop and look closely.","visual","Fill the panels with chatter, then make the reaction panel completely silent for the laugh."],
    "theLie": [4,"The lie a character believes makes the choices that cause their trouble.","The lie is usually the opposite of the theme.","The audience waits for the lie to break.","thought","Show the lie working once before it fails."],
    "timeOfDay": [2,"Time of day is the plot's clock: night brings danger, morning brings a new start.","Day and night carry hope and fear.","A jump in the time of day tells the audience time has passed and things have moved.","visual","Put the darkest choice at night and the answer at dawn."],
    "timePerCharacter": [2,"Giving more screen time to someone tells the audience their story is about to matter more.","Who the film spends time with shows whose life it values.","When a minor character suddenly gets more time, the audience wonders why.","visual","Give a background character slightly more time each scene until they become important."],
    "toneArc": [2,"Where a tone of voice lands in the story marks whether we are still building or already in the climax.","A tone that comes back at the end changed shows how far the film has traveled.","When the voice shifts tone, the audience senses the story has moved to a new stage.","audio","Use the same line in the opening and the ending with a different tone of voice."],
    "topper": [1,"Each topper squeezes one more turn out of a moment before the plot moves on.","Toppers that keep growing show a world where things only get worse, or sillier.","Just when the laugh fades, the audience learns there may be one more coming and keeps watching.","thought","Let the laugh die, then add one small line from the background."],
    "touch": [2,"A first touch can mark the moment a relationship changes and moves forward.","Who reaches out and who pulls away shows care, power and trust.","A hand moving toward someone makes the audience wait to see if it lands.","movement","Have the listener be the one to touch first, and let the speaker lose their train of thought."],
    "transition": [2,"A transition can link two scenes so the second feels like an answer to the first.","Matching cuts tie ideas together.","A clever transition carries attention across the cut.","visual","Match a shape or sound from the end of one scene to the start of the next."],
    "turbulence": [1,"Calm drifting air turning into wild swirls shows a situation sliding out of control.","Calm air feels like peace; churning, chaotic air feels like a mind in turmoil.","Wild swirling motion keeps the eye restless, so the audience feels unsettled heading into the next beat.","movement","Keep the smoke drifting calmly until the lie comes out, then make it swirl wildly."],
    "twoRoads": [4,"One rising while the other falls sets up a moment when their paths cross.","Two roads moving against each other show how one person's gain can be another's loss.","The audience waits for the moment the two roads meet.","plot","Put the crossing point of their roads in the same scene."],
    "typeClash": [3,"Opposite personalities stuck together keep making the plot harder by wanting different things.","Opposites learning to need each other is a theme of growing by meeting your opposite.","The audience waits for the next time the two types rub and spark.","thought","Lock two opposite types in one small space with one task."],
    "understatement": [1,"Shrugging off a disaster lets the plot pile on more trouble without the scene stopping to mourn.","Treating a huge thing as tiny shows people coping, or refusing to face what is happening.","The audience waits for the moment the character finally admits how big this really is.","audio","Have them describe the burning house as a bit warm."],
    "unwantedGuest": [3,"The unwanted guest threatens the event, and the plot becomes getting rid of them.","Who is unwanted, and why, shows what a group is trying to keep out.","The audience waits for the guest to say the one thing that ruins everything.","plot","Let the guest stay longer than anyone can stand, then leave with a parting shot."],
    "valueKey": [1,"The whole picture getting darker section by section tells the audience the story is sliding toward its lowest point.","Bright, airy scenes feel hopeful and open; dark ones feel secret, adult and dangerous.","A jump from a dark scene to a bright one feels like coming up for air, and the audience follows the release.","visual","Keep comedy scenes bright and even, then drop the brightness hard for the one scene that is not a joke."],
    "visualDensity": [1,"A frame filling with more and more stuff shows things getting crowded and harder to handle.","Busy frames feel like crowded, overwhelming lives; empty frames feel lonely or peaceful.","When a busy frame suddenly empties, the audience notices the one thing left and looks right at it.","visual","Pack the frame with clutter, then cut to an empty room with only the character in it."],
    "visualGag": [1,"A gag in the background can plant a clue the plot uses later.","What sits quietly in the frame can mock or agree with what the characters are saying.","Once the audience spots one hidden joke, they start searching every frame for the next.","visual","Put a sign in the background that says the opposite of what the hero claims."],
    "vocalTone": [2,"The tone under the words tells us what the person really wants, which is where the plot really goes.","A tone that fights the words is where theme hides.","A tone that does not fit the words makes the audience listen harder.","audio","Say the threat sweetly."],
    "volume": [2,"A voice getting louder pushes a scene toward a breaking point.","Who shouts and who whispers says who holds power.","A sudden change in loudness grabs attention.","audio","Drop to a whisper for the line that matters most."],
    "walkAndTalk": [2,"Walking while talking makes a conversation feel like it is heading somewhere and has a deadline.","Walking together or splitting apart shows if people are on the same path.","Moving through space keeps the eye busy while the talk carries the plot.","movement","End the walk at a door that one character goes through and the other cannot."],
    "wallArt": [1,"A picture on the wall can hold a clue, a memory or a secret the plot will use.","Art on the walls shows what the owners love and fear.","A photo or painting the camera lingers on becomes a question.","thought","Let the camera rest on one picture that comes back later."],
    "warmCool": [1,"A picture turning warm or cool can show a relationship warming up or going cold.","Warm feels safe and close; cool feels lonely, distant or tense.","When the warmth drains from a scene, the audience feels trouble coming.","visual","Start the dinner warm and cool the picture slowly as the argument grows."],
    "warmth": [3,"Warming or cooling between two people sets up the moment they come together or fall apart.","How warm people become shows what the film thinks about friendship and love.","The audience follows the warmth and wants to know where it will end.","thought","Cool the relationship just before the moment one needs the other most."],
    "wear": [2,"Things getting more worn, dusty or rusted shows time passing or a place falling apart.","Wear shows history: a scratched table or stained wall tells us what life has done to people here.","A spotless object in a ruined room stands out, and the audience wonders why it alone survived.","visual","Show the same room new at the start and ruined at the end, with one item left untouched."],
    "weather": [2,"Weather can block a road, force people together or clear the way, moving the plot without anyone deciding to.","Weather mirrors the inner state, so it carries the feeling of the theme.","A change in the sky makes the audience expect a change on the ground.","visual","Let the weather build as the tension builds, and break when it breaks."],
    "wetness": [2,"Surfaces going from dry to soaked show a storm arriving or a struggle getting messier.","Getting soaked strips away dignity and shows characters worn down or washed clean.","Dripping water keeps small things moving in the shot and promises that more is coming down.","visual","Make the hero more soaked in each scene of the chase, and drench the snob completely for the laugh."],
    "whoKnows": [4,"The secret is the plot's ticking clock: everything changes the moment it comes out.","Who knows and who doesn't is the theme of trust and lies.","The audience waits for the secret to slip out, and watches every near miss.","plot","Tell the audience the secret first, then put the one person who doesn't know in the room."],
    "whoMoves": [2,"The person who moves is taking action; the one who stays still is waiting for something to happen.","Who acts and who waits is a theme of power.","The one moving gets the attention; the still one gets it when they finally move.","movement","Keep the main character still until they decide, then move them."],
    "windForce": [2,"Wind rising from a breeze to a gale signals a storm, literal or emotional, is about to hit.","Wind pushing against characters shows forces bigger than them that they must stand against.","Gusts make everything in the shot move at once, raising the audience's sense that something is coming.","movement","Let a strong gust steal the hat, paper or toupee at the worst possible moment."],
    "wordplay": [1,"A misunderstanding about a word can send a character off on the wrong errand and steer the plot.","Who wins the comeback shows who is sharp and who is losing control.","Quick trading of lines makes the audience listen hard so they do not miss the next one.","audio","Plant a word early and turn its meaning upside down in the last line of the scene."],
    "wordsAmount": [2,"What gets said, or not said, decides what the other characters learn and do.","Talking around a feeling is the theme of people who cannot say what they mean.","After a lot of talk, a sudden silence makes the audience wait for the next word.","audio","Let them talk nonstop, then answer the only real question with silence."],
    "wound": [4,"The old hurt explains why the character keeps making the same choice, and the plot pushes on that sore spot.","The wound is what the film is really about healing, or failing to heal.","Touching the wound without explaining it makes the audience wait to learn what happened.","thought","Let someone joke about the wound early, so the laugh dies and the audience wants to know why."],
  };
  const CUES = ["visual", "audio", "thought", "movement", "plot"];
  DB.MOMENTUM_CUES = CUES;
  DB.data.curiosities.forEach((c) => {
    const n = NOTES[c.id];
    if (!n) return;
    c.momentum = { push: n[0], plot: n[1], theme: n[2], pull: n[3], cue: n[4], tryThis: n[5] };
    DB.curiosity({
      id: c.id,
      sliders: [
        { id: "push", label: "Pushes the story", range: { min: 0, max: 5 }, from: n[0], to: Math.min(5, n[0] + 2), plain: "How much this curiosity moves the story forward here." },
        { id: "pointsAhead", label: "Points ahead", scale: ["closes a door", "holds", "hints at what's next", "demands what's next"], from: "holds", to: "demands what's next", plain: "Whether it settles something or leaves a question the next moment must answer." },
        { id: "themeLink", label: "Tied to a theme", scale: ["not at all", "loosely", "clearly", "it is the theme"], from: "loosely", to: "clearly", plain: "How closely it carries one of the film's themes here." },
      ],
    });
  });
})(typeof window !== "undefined" ? window.CuriosityDB : require("./curiosity-db.js"));
